lq('බෝග වර්ගය අනුව බිම් සැකසීමේ ක්‍රමය වෙනස් වීමට හේතුව කුමක්ද?','විවිධ බෝගවල වර්ධන අවශ්‍යතා වෙනස් වන නිසා','සියලු බෝගවල අවශ්‍යතා සමාන නිසා','බෝගයට පස අවශ්‍ය නොවන නිසා','බීජයේ වර්ණය නිසා පමණි','a'),lq('සුදුසු බිම් සැකසීමක් මඟින් බෝගයේ මුල් පද්ධතියට ලැබෙන වාසිය කුමක්ද?','පස තුළ පහසුවෙන් පැතිරී වර්ධනය වීමට හැකි වීම','මුල් වර්ධනය නතර වීම','මුල් පසෙන් පිටත පමණක් වර්ධනය වීම','ජලය අවශෝෂණය නතර වීම','a'),lq('බිම් සැකසීමේදී භූමියේ ස්වභාවය සැලකිල්ලට ගැනීම වැදගත් වන්නේ ඇයි?','සුදුසු බිම් සැකසුම් ක්‍රමය තෝරාගැනීමට','සියලු ඉඩම් එකම ක්‍රමයට සකස් කළ යුතු නිසා','භූමියේ ස්වභාවය බෝගයට බලපාන්නේ නැති නිසා','අස්වනු නෙළීමට පමණක්','a'),lq('නිසි බිම් සැකසීමක අවසාන අරමුණට වඩාත් ගැළපෙන්නේ කුමක්ද?','බෝග ස්ථාපනය හා වර්ධනය සඳහා සුදුසු පරිසරයක් සැපයීම','බෝගයට අහිතකර පරිසරයක් ඇති කිරීම','පස සම්පූර්ණයෙන් ඉවත් කිරීම','ජලය හා පෝෂක නොලැබීමට සැලැස්වීම','a'),lq('“බිම් සැකසීම” පිළිබඳ වඩාත් නිවැරදි ප්‍රකාශය කුමක්ද?','බෝගයක් සිටුවීමෙන් පසු පමණක් සිදුකරන ක්‍රියාවලියකි','පසෙහි සියලු ජීවීන් විනාශ කිරීමේ ක්‍රියාවලියකි','බෝගය සාර්ථකව ස්ථාපනය කර වර්ධනය කිරීමට සුදුසු පාංශු පරිසරයක් සකස් කිරීමේ ක්‍රියාවලියකි','අස්වනු ගබඩා කිරීමේ ක්‍රියාවලියකි','c')];
$db=db();$l=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Agriculture and Food Technology' AND l.medium='Sinhala' AND l.display_order=5 AND l.status='active' LIMIT 1");if(!$l)throw new RuntimeException('Grade 10 Agriculture lesson 5 not found');$q=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' ORDER BY id LIMIT 1",'i',[(int)$l['id']]);if(!$q)throw new RuntimeException('Lesson 5 quiz not found');$id=(int)$q['id'];$db->begin_transaction();try{$s=$db->prepare("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=? AND qq.activity_type='challenge'");$s->bind_param('i',$id);$s->execute();$s=$db->prepare("DELETE FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge'");$s->bind_param('i',$id);$s->execute();$s=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");foreach($qs as $i=>$v){[$t,$o,$k,$e]=$v;$p=$i+1;$s->bind_param('isssssssi',$id,$t,$o[0],$o[1],$o[2],$o[3],$k,$e,$p);$s->execute();}$db->query("UPDATE quizzes SET title_si='5 වන පාඩම — MCQ ප්‍රශ්න 30',timer_minutes=30,pass_mark=50 WHERE id=$id");$c=(int)(query_one("SELECT COUNT(*) n FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$id])['n']??0);if($c!==30)throw new RuntimeException("Expected 30 MCQs, found $c");$db->commit();echo "Grade 10 Agriculture lesson 5 replaced with 30 MCQs.\n";}catch(Throwable $e){$db->rollback();throw $e;}
